async function finalAttempts() {
  // Attempt to kill any remaining target that might be nearby
  const targets = ["Imp", "Woman", "Man", "Rat"];
  let killed = [];

  for (const target of targets) {
    const result = await bot.attack(target);
    if (result.success) {
      await sdk.waitForCondition(state => {
        const player = state.player;
        return !player || !player.combat.inCombat;
      }, 10000);
      killed.push(target);
    }
  }
  return killed;
}

return await finalAttempts();
